mapper.select:
SELECT COUNT(*)
FROM growth_exp_logs
WHERE workspace_id = #{workspaceId}
	AND notice_id = #{noticeId}
	AND action_type = #{actionType}

SELECT exp_log_id AS "expLogId", exp
FROM growth_exp_logs
WHERE workspace_id = #{workspaceId}
	AND notice_id = #{noticeId}
	AND action_type = #{actionType}
	AND deleted_at IS NULL

mapper.update:
UPDATE growth_exp_logs SET deleted_at = SYSDATE
WHERE exp_log_id = #{expLogId} 
	AND deleted_at IS NULL

mapper.select:
SELECT COUNT(*)
FROM growth_exp_logs
WHERE workspace_id = #{workspaceId}
	AND member_id = #{memberId}
	AND action_type = #{actionType}

SELECT COUNT(*)
FROM workspace_invites
WHERE accepted_member_id = #{memberId}
	AND workspace_id = #{workspaceId}
	AND invite_key = #{inviteKey}
	AND status = 0
	AND invite_status = 1
	AND accepted IS NOT NULL
	AND EXISTS (
		SELECT 1
		FROM workspace_members wm
		WHERE wm.workspace_id = #{workspaceId}
			AND wm.member_id = #{memberId}
			AND wm.status = 0
			AND wm.left IS NULL
	)

